def read_headers(fn):
    with open(fn,'rb') as f:
        off=0; hdu=0
        while True:
            cards=[]
            while True:
                block=f.read(2880)
                if not block: return
                off += 2880
                for j in range(0,2880,80):
                    card=block[j:j+80].decode('ascii','ignore')
                    cards.append(card)
                    if card.startswith('END'):
                        header={}
                        for c in cards:
                            k,v=parse_card(c)
                            if k: header[k]=v
