        try: return key, int(val)
        except: pass
        try: return key, float(val)
        except: return key, val
    return key,None

def bintable_header(fn):
    with open(fn,'rb') as f:
        while True:
            cards=[]
            while True:
                block=f.read(2880)
                if not block: return None,None
                for j in range(0,2880,80):
                    card=block[j:j+80].decode('ascii','ignore')
                    cards.append(card)
                    if card.startswith('END'):
                        h={}
                        for c in cards:
                            k,v=parse_card(c)
                            if k: h[k]=v
                        data_start=f.tell()
                        if h.get('XTENSION')=='BINTABLE': return h,data_start
                        bitpix=h.get('BITPIX',0); naxis=h.get('NAXIS',0); size=0
                        if naxis:
                            prod=1
                            for i in range(1,naxis+1): prod*=int(h.get(f'NAXIS{i}',0))
                            size=abs(bitpix)//8*prod
                        f.seek(size+(2880-size%2880)%2880,1)
                        break
                else: continue
                break

def item_size(tform):
    m=re.match(r'(\d*)([A-Z])', tform); n=int(m.group(1) or 1); c=m.group(2)
    sz={'L':1,'X':0,'B':1,'I':2,'J':4,'K':8,'A':1,'E':4,'D':8}[c]*n
    return sz
for fn in ['/assets/Gaia_DR2/gaiadr2_RVSall.fits','/assets/Gaia_DR2/gaiadr2_l0all.fits','/assets/Gaia_DR2/gaiadr2_l180all.fits']:
